import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const base='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8')),save=(p:string,v:unknown)=>writeFileSync(p,JSON.stringify(v,null,2)+'\n');
const measure=read('.git/b11-secret-measure.json'),faults=read('.git/b11-secret-faults.json'),compat=read('.git/b11-secret-compat.json'),native=read('.git/b11-secret-old-runtime.json');
const inputs=measure.sourceInputs,paths=inputs.map((r:any)=>r.path),evidence=base+'evidence/B11.74.5-secret.json';
for(const input of inputs){assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));for(const record of [faults,compat,native])assert(record.sourceInputs.some((r:any)=>r.path===input.path&&r.sourceHash===input.sourceHash));}
for(const record of [compat,...native.runs]){assert.equal(record.exit,0);assert(record.output.includes('13 pass')&&record.output.includes('0 fail')&&record.output.includes('572 expect()'));}
assert.equal(faults.runs.length,8);assert.equal(faults.runs[0].exit,0);for(const record of faults.runs.slice(1)){assert.equal(record.exit,1);assert(record.output.includes('(fail)'));}
const coverage=createCoverageMap(measure.measurement.rawCoverage);
for(const entry of measure.measurement.files)assert.deepEqual(coverage.fileCoverageFor(resolve(entry.path)).toSummary().data,entry.metrics);
assert.equal(measure.measurement.files[0].metrics.branches.pct,95.89);for(const m of Object.values(measure.measurement.files[1].metrics) as any[])assert.equal(m.pct,100);
assert(readFileSync('.git/b11-secret-red-corrected.txt','utf8').includes('5 fail'));
assert.equal(readFileSync('.git/b11-secret-test-types.txt','utf8').trim(),'');assert(readFileSync('.git/b11-secret-isolation.txt','utf8').includes('PASS (no violations)'));
const runtimeRoot=native.runs[0].command[0].match(/^(.*memory-native-compat-[^\\/]+)[\\/]/)?.[1];assert(runtimeRoot&&!existsSync(runtimeRoot));
const source=readFileSync(paths[0],'utf8');assert.equal([...source.matchAll(/\.prepare[<(]/g)].length,4);assert.equal([...source.matchAll(/using \w+ =/g)].length,4);
const record={item_id:'B11.74.5',status:'secret-audit database lifetime and demonstrated rollback/acknowledgement repairs locally verified; full Q101 security acceptance remains open',recordedAt:new Date().toISOString(),startingRevision:'998d8a8da8d0d76cdfe70eb1d6a75f452cabd44b',cwd:process.cwd(),sourceInputs:inputs,
 changes:['Four prepares dispose within operation/table scopes.','Requested database redaction and FTS rebuild share one synchronous immediate transaction; nested caller work is preserved.','Ignored updates reject instead of reporting successful redaction.'],
 red:[{command:'bun test --timeout 15000 tests/infrastructure/database/secret-audit-lifecycle.test.ts',exit:1,output:readFileSync('.git/b11-secret-red-corrected.txt','utf8'),scope:'Five initial native tests reproduce lifetime, partial update/index failure and ignored-write acknowledgement defects. Initial earlier attempt had a mistyped trigger fixture name; corrected before implementation.'}],
 checks:[compat,{command:'bun run typecheck',exit:0,output:readFileSync('.git/b11-secret-types.txt','utf8')},{command:'bun node_modules/typescript/bin/tsc --project .git/b11-secret-tests-tsconfig.json',exit:0,config:readFileSync('.git/b11-secret-tests-tsconfig.json','utf8'),output:readFileSync('.git/b11-secret-test-types.txt','utf8')},{command:'bun run test:isolation',exit:0,output:readFileSync('.git/b11-secret-isolation.txt','utf8')}],native,removedRuntimeRoot:runtimeRoot,diagnosticCoverage:measure,decisionChecks:faults,
 otherInputs:['src/infrastructure/database/owned-database.ts','src/infrastructure/database/schema.ts','src/infrastructure/security/pattern-redactor.ts','src/domain/entities/memory-event.ts','src/domain/ports/redactor.ts','src/infrastructure/paths.ts','tests/helpers/owned-test-directory.ts'].map(path=>({path,sourceHash:sourceHash(readFileSync(path,'utf8'))})),
 limits:['Production diagnostic branches95.89% fails Tier S; driver100% and seven scoped faults do not establish full security or decision coverage.','Database transaction does not cover event-log quarantine or report publication. Full surface inventory, derived vectors/hashes, redactor error policy, adversarial persistence and secret-free metadata remain Q101.','No canonical memory/store, installed CLI, production replication or model experiment changed. Main factory remains unchanged.','Native Windows scoped proof only; full suite, Linux, supported floor, installed recovery, complete measurement and independent review remain open. Owned runtime and diagnostic directories removed.'],
 validation:{command:'bun .git/b11-secret-checkpoint.ts',source:readFileSync('.git/b11-secret-checkpoint.ts','utf8'),exit:0,result:'Current hashes, paired runtime group, seven detected faults and diagnostic metrics reconcile; full security remains open.'}};
const catalog=discoverInventory(process.cwd()),manifest=read(base+'quality-classifications.json'),ledger=read(base+'work-items.json'),get=(id:string)=>ledger.items.find((i:any)=>i.id===id);
assert(!get('Q101'),'Checkpoint already recorded');assert.equal(catalog.files.length,462);
for(const path of paths){const file=catalog.files.find(f=>f.path===path)!;let row=manifest.files.find((r:any)=>r.path===path);if(!row){row={path,package:file.package,tier:'S',rationale:'Native security and destructive redaction regression driver.',applicability:{mode:'measure',reason:'Executable security driver; no exclusion approved.'},decisionStatus:'proposed - independent review pending'};manifest.files.push(row);}
 row.sourceHash=file.sourceHash;row.inspection={sourceRevision:'998d8a8 + current source hash',anchor:'native audit database lifetime/rollback/acknowledgement',scope:'Database slice only; full security Q101 remains open.'};const metrics=measure.measurement.files.find((r:any)=>r.path===path).metrics;
 row.metricApplicability={status:'diagnostic - B05/Q101/B11.74.7 and independent review pending',evidence,sourceHash:file.sourceHash,disposition:'Production branches95.89% fails Tier S; driver100%. Scope is database behavior, not complete secret remediation.',metrics:Object.fromEntries(Object.entries(metrics).map(([name,value]:[string,any])=>[name,{observedCounterTotal:value.total,proposal:'measure - completeness unverified'}]))};
}
manifest.files.sort((a:any,b:any)=>a.path.localeCompare(b.path));assert.deepEqual(validateInventory(catalog,manifest),[]);
ledger.items.push({id:'Q101',stage:'baseline-quality',title:'Complete secret-audit remediation safety and Tier S quality',status:'pending',depends_on:['B11.74.5'],scope:'SecretAuditService, quarantine/report persistence, derived data and installed audit-secrets callers',deliverable:'Complete sensitive-surface inventory; safe quarantine/replacement and truthful partial outcomes; derived-state consistency; redactor error and metadata disclosure policy; final security acceptance.',verification:'Native filesystem/database failure and retry, concurrent append, collision, persisted-value/adversarial secret-free report tests; installed public CLI and four per-file metrics>=95%, Tier S branches100%, decision checks and independent review.',risk:'S',authorization:'authorized',owner:'memory-nexus',evidence:[evidence,'docs/plans/2026-09-22-secret-audit-database-integrity.md'],acceptance_record:base+'evidence/Q101.json',observed_gap:'Production branches95.89%. Database partial failures and ignored writes repaired; filesystem replacement, complete surfaces/derived data, redactor fallback and metadata disclosure require security proof.',retirement_trigger:'Before B11.74.7/B10/R02 acceptance.'});
for(const barrier of ['B11.74.7','B10'])get(barrier).depends_on.push('Q101');
